object Solution {
  def earliestAndLatest(n: Int, firstPlayer: Int, secondPlayer: Int): Array[Int] = {
    import scala.collection.mutable

    // Memoization cache: Map[(n, first, second) -> (earliest, latest)]
    val memo = mutable.Map.empty[(Int, Int, Int), (Int, Int)]

    def dfs(n: Int, f: Int, s: Int): (Int, Int) = {
      if (memo.contains((n, f, s))) return memo((n, f, s))
      // If they meet this round
      if (f + s == n + 1) {
        memo((n, f, s)) = (1, 1)
        return (1, 1)
      }

      val nextPlayers = mutable.ArrayBuffer.empty[(Int, Int)] // (original pos, new pos)
      val half = n / 2
      val isOdd = (n % 2 == 1)
      val mid = if (isOdd) half + 1 else -1

      // Positions of players in this round: 1..n
      // The pairs are (i, n - i + 1) for i in 1..half
      // The middle player (if odd) automatically advances

      // We want to simulate all possible outcomes of the matches except the one involving f and s,
      // because f and s always win until they meet.

      // We consider all possible ways the other players can win or lose to maximize or minimize rounds.

      // The key is to consider the next round's positions of f and s after this round.

      // For each pair (i, j = n - i + 1):
      // - If (f, s) are in this pair, they meet this round (already handled above)
      // - If one of them is in the pair, that player wins and advances
      // - If none of them are in the pair, either player can win (we choose both possibilities)

      // We will build all possible next rounds' player lists and find min and max rounds recursively.

      // To do this efficiently, we use a backtracking approach.

      // We'll represent the current round players as 1..n, with f and s known.

      // We want to generate all possible next round player lists, but only track the positions of f and s.

      // Because the players are sorted by original number in the next round, the positions of f and s in next round
      // depend on which players advance.

      // Let's implement a backtracking function to generate all possible next rounds' (f', s') positions.

      val results = mutable.ArrayBuffer.empty[(Int, Int)]

      // We will represent the pairs as a list of pairs:
      val pairs = (1 to half).map(i => (i, n - i + 1)).toArray

      // We want to generate all possible winners for pairs that do not contain f or s.
      // For pairs containing f or s, winner is fixed.

      // We'll do backtracking over pairs to generate all possible winners.

      def backtrack(idx: Int, winners: mutable.ArrayBuffer[Int]): Unit = {
        if (idx == pairs.length) {
          // Add middle player if odd
          if (isOdd) winners += mid

          // Sort winners by original number
          val sorted = winners.sorted

          // Find new positions of f and s in sorted
          val nf = sorted.indexOf(f) + 1
          val ns = sorted.indexOf(s) + 1

          // Recurse
          val (earliest, latest) = dfs(sorted.length, nf, ns)
          results += ((earliest, latest))

          if (isOdd) winners.remove(winners.length - 1)
          return
        }

        val (a, b) = pairs(idx)

        // Check if pair contains f or s
        val containsF = (a == f || b == f)
        val containsS = (a == s || b == s)

        if (containsF && containsS) {
          // They meet this round (already handled above)
          // Should not reach here
          return
        } else if (containsF) {
          // f wins
          winners += f
          backtrack(idx + 1, winners)
          winners.remove(winners.length - 1)
        } else if (containsS) {
          // s wins
          winners += s
          backtrack(idx + 1, winners)
          winners.remove(winners.length - 1)
        } else {
          // Neither f nor s in this pair, either a or b can win
          winners += a
          backtrack(idx + 1, winners)
          winners.remove(winners.length - 1)

          winners += b
          backtrack(idx + 1, winners)
          winners.remove(winners.length - 1)
        }
      }

      backtrack(0, mutable.ArrayBuffer.empty)

      val earliest = results.map(_._1).min + 1
      val latest = results.map(_._2).max + 1

      memo((n, f, s)) = (earliest, latest)
      (earliest, latest)
    }

    val res = dfs(n, firstPlayer, secondPlayer)
    Array(res._1, res._2)
  }
